```c
/* fma_dual_kernel.c — dual-channel extraction of sdcshield test `fma`
 * (tests/cpu/fma/fma.cpp @ 07be34e2).
 * Channel A (detection semantics preserved): NEON vfmaq_f32 vs fmaf
 *   software reference + store/reload consistency; first mismatch stops
 *   the loop (sdcshield report_fail semantics), counted in g_fails.
 * Channel B (independent oracle): FNV-1a over every iteration's hardware
 *   result vector (escape/masked separation for clean runs).
 * Adaptations (documented, detection-neutral): random_device{}() seed ->
 *   fixed seed 42 (determinism); test_time_condition -> fixed ITERS.
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <arm_neon.h>

#define VECTOR_SIZE 8
#ifndef ITERS
#define ITERS 200000
#endif

static uint64_t g_fails = 0;

static uint64_t fnv1a(uint64_t h, const void *p, size_t n) {
    const uint8_t *b = (const uint8_t *)p;
    for (size_t i = 0; i < n; i++) { h ^= b[i]; h *= 1099511628211ULL; }
    return h;
}

/* xorshift32 PRNG standing in for std::mt19937 + uniform_real_distribution
 * (deterministic, no libstdc++ dependency for a static C build) */
static uint32_t xs32(uint32_t *s) {
    uint32_t x = *s; x ^= x << 13; x ^= x >> 17; x ^= x << 5; *s = x; return x;
}
static float frand(uint32_t *s, float lo, float hi) {
    return lo + (hi - lo) * ((float)xs32(s) / 4294967295.0f);
}

static void software_fma(const float *a, const float *b, const float *c, float *ref) {
    for (int i = 0; i < VECTOR_SIZE; ++i) ref[i] = fmaf(a[i], b[i], c[i]);
}
static int approx_equal(const float *x, const float *y) {
    for (int i = 0; i < VECTOR_SIZE; ++i) {
        float diff = fabsf(x[i] - y[i]);
        float tol = 1e-6f * fmaxf(fabsf(x[i]), fabsf(y[i]));
        if (diff > tol && diff > 1e-7f) return 0;
    }
    return 1;
}

int main(void) {
    alignas(16) float a[VECTOR_SIZE], b[VECTOR_SIZE], c[VECTOR_SIZE];
    alignas(16) float result[VECTOR_SIZE];
    float ref[VECTOR_SIZE];
    uint32_t seed = 42;
    uint64_t h = 1469598103934665603ULL;

    for (uint32_t it = 0; it < ITERS; it++) {
        for (int i = 0; i < VECTOR_SIZE; i++) {
            a[i] = frand(&seed, -100.0f, 100.0f);
            b[i] = frand(&seed, -100.0f, 100.0f);
            c[i] = frand(&seed, -100.0f, 100.0f);
        }
        float32x4_t va_l = vld1q_f32(a), va_h = vld1q_f32(a + 4);
        float32x4_t vb_l = vld1q_f32(b), vb_h = vld1q_f32(b + 4);
        float32x4_t vc_l = vld1q_f32(c), vc_h = vld1q_f32(c + 4);
        vst1q_f32(result,     vfmaq_f32(vc_l, va_l, vb_l));
        vst1q_f32(result + 4, vfmaq_f32(vc_h, va_h, vb_h));
        h = fnv1a(h, result, sizeof result);            /* channel B */
        software_fma(a, b, c, ref);
        float store_buf[VECTOR_SIZE], reload_buf[VECTOR_SIZE];
        memcpy(store_buf, result, sizeof store_buf);
        memcpy(reload_buf, store_buf, sizeof reload_buf);
        if (!(approx_equal(result, ref) &&
              memcmp(reload_buf, result, sizeof reload_buf) == 0)) {
            g_fails++;                                  /* channel A */
            break;               /* sdcshield report_fail = stop on first */
        }
    }
    printf("SDCSHIELD_FAILS=%llu\n", (unsigned long long)g_fails);
    printf("FINAL=%016llx\n", (unsigned long long)h);
    return g_fails ? 1 : 0;
}
```

